import type { CompletionEvidence } from './contract.ts'
export function completionIsCurrent(evidence:{revision:number;head:string}|undefined,revision:number,remoteHead:string){return Boolean(evidence&&evidence.revision===revision&&evidence.head===remoteHead)}
export async function findCurrentCompletion(evidences:CompletionEvidence[],opts:{revision:number;repository:string;issue:number;remoteHead:(pr:number)=>Promise<string|undefined>}){const matching=evidences.map(x=>x.externalCompletion).filter(x=>x.revision===opts.revision&&x.repository===opts.repository&&x.issue===opts.issue).sort((a,b)=>b.pr-a.pr);for(const e of matching){const head=await opts.remoteHead(e.pr);if(head&&completionIsCurrent({revision:e.revision,head:e.head},opts.revision,head))return e}return undefined}
